// Einstellungen kommen aus Umgebungsvariablen des n8n-Containers – nie Werte ins Repo schreiben.
const env = k => { try { return $env[k]; } catch (e) { return undefined; } };
const qh = String(env('EMMA_QUIET_HOURS') || '22-7').split('-').map(Number); // Ruhezeit "von-bis" (volle Stunden, Europe/Berlin)
const [quietFrom, quietTo] = qh.length === 2 && qh.every(Number.isInteger) ? qh : [22, 7];
const cfg = {
  core_os_url: String(env('EMMA_CORE_OS_URL') || '').replace(/\/$/, ''),
  budget_eur: Number(env('EMMA_BUDGET_EUR') || 5),
  daily_docs: String(env('EMMA_DAILY_DOCS') || 'on') !== 'off',
  approvals_per_day: Math.max(0, Number(env('EMMA_MAX_APPROVALS_PER_DAY') || 5)), // Obergrenze fuer Freigabe-Anfragen pro Tag
  quiet_from: quietFrom,
  quiet_to: quietTo,
};
if (!cfg.core_os_url) throw new Error('EMMA_CORE_OS_URL ist nicht gesetzt – ohne core-os arbeitet EMMA nicht.');
return [{ json: cfg }];

// Nur bekannte Arten mit gueltigem Inhalt. Ungueltiges wird NICHT still verworfen, sondern bricht laut ab (Fehler im Ausfuehrungsprotokoll).
// Ohne Vorschlaege (leerer Aufruf, z. B. morgens) entsteht ein Flush-Signal: dann werden nur aufgeschobene Anfragen nachgeholt.
const KINDS = ["run_engine", "write_note", "write_draft", "calendar_event", "create_workflow"];
const ENGINES = ["SUPERNOVA", "FINANCE", "LEGAL", "INTEL", "VENTURE", "LEAD", "SALES", "REACTIVATION", "PRICING", "CONTENT", "SOCIAL", "WORDPRESS", "SHOPIFY", "GITHUB", "TASKS", "GOOGLE_SUITE", "GUARDIAN", "EMAIL_VALIDATION", "CHART", "MEDIA", "EVOLUTION", "GENERAL"];
const MAX_BYTES = 60000;
const iso = v => !isNaN(Date.parse(v));
const check = p => {
  if (!p || !KINDS.includes(p.kind)) return 'unbekannte Art';
  if (!p.summary) return 'Zusammenfassung fehlt';
  const x = p.payload || {};
  if (JSON.stringify(x).length > MAX_BYTES) return 'Inhalt zu gross';
  switch (p.kind) {
    case 'run_engine': return ENGINES.includes(String(x.engine || '').toUpperCase()) && x.text ? '' : 'Engine oder Text fehlt';
    case 'write_note': case 'write_draft': return x.title && x.content ? '' : 'Titel oder Inhalt fehlt';
    case 'calendar_event': return x.title && iso(x.start) && iso(x.end) ? '' : 'Titel oder Zeit fehlt';
    case 'create_workflow': return /^EMMA_AUTO_[A-Z0-9_]{1,60}$/.test(String(x.workflow_name || '')) && x.workflow_json && Array.isArray(x.workflow_json.nodes) ? '' : 'Workflow-Name oder Nodes fehlen';
  }
  return 'unbekannte Art';
};
const incoming = $('Vorschlag').all().map(i => i.json).filter(p => !(p && p._flush));
if (!incoming.length) return [{ json: { kind: '_flush', summary: '', payload: {}, source: 'flush' } }];
const errors = incoming.map(p => ({ p, e: check(p) })).filter(x => x.e).map(x => `${x.p && x.p.kind || '?'}: ${x.e}`);
if (errors.length) throw new Error('Vorschlag abgelehnt - ' + errors.slice(0, 3).join('; '));
return incoming.map(p => ({ json: { kind: p.kind, summary: String(p.summary).slice(0, 300), payload: p.payload || {}, source: String(p.source || 'n8n') } }));

